mapper.update:
UPDATE sys07_role_menu
   SET sys07_use_yn = #{useYn}
 WHERE sys07_role_menu_id = #{id}
   AND sys07_role_id      = #{roleId}

mapper.select:
SELECT 
  FROM sys06_menu m
       LEFT JOIN sys07_role_menu r ON r.sys07_menu_id = m.sys06_menu_id AND r.sys07_role_id = #{roleId}
 WHERE m.sys06_menu_id = #{menuId}
